import { ComponentType, ReactElement, ReactFragment, ReactPortal, ReactText } from 'react';
import type { ConvertibleUnit, FormatOptions, Unit } from '@dynatrace-sdk/units';
import { DataTableContextConfig } from './table-config-types.js';
import type { CustomColorPalette, ColorPalette } from '../../charts/core/types/color-palette.js';
import { ThresholdOptions, Threshold } from '../../core/types/threshold-types.js';
import type { UseAlignmentColumnOptions } from '../plugins/use-column-alignment/useColumnAlignment.js';
import type { UseColumnSizesColumnOptions } from '../plugins/use-column-sizes/column-size-types.js';
import type { UseColumnTypesColumnOptions } from '../plugins/use-column-types/useColumnTypes.js';
import type { UseColumnUserActionsProps } from '../plugins/use-user-actions/useUserActions.types.js';
/**
 * Used in combination with the DataTable. A table column
 * can either be a single column or a column group.
 */
export type TableColumn = SingleColumn | ColumnGroup;
/**
 * Defines the options passed to the format function.
 */
export type UseFormattingOptions = {
    formatter?: FormatOptions<Unit, ConvertibleUnit>;
};
/**
 * Defines how a table cell for this column is rendered.
 */
export type ColumnType = 'text' | 'date' | 'bit' | 'number' | 'sparkline' | 'meterbar';
/**
 * Defined config options used in sparkline column
 */
export type SparklineColumnConfig = {
    color?: string;
    variant?: 'line' | 'area';
};
/**
 * Used to represent DataTable columns that can contain sparkline chart
 * and based on that certain config options
 */
export type SparklineColumn = {
    columnType: 'sparkline';
    config?: SparklineColumnConfig;
};
/**
 * Defined configuration options used in meterbar column.
 */
export type MeterbarColumnConfig = {
    color?: string;
    min?: number;
    max?: number;
    colorPalette?: ColorPalette | CustomColorPalette;
    showTooltip?: boolean;
    thresholds?: {
        value: number;
        color: string;
        name: string;
    }[];
};
/**
 * Used to represent DataTable columns that can contain
 * meterbar chart and, based on that, certain config options
 */
export type MeterbarColumn = {
    columnType: 'meterbar';
    config?: MeterbarColumnConfig;
};
/**
 * Columns normally either have a function or string accessor. Technically
 * the can also have no accessor. These types (WithFunctionAccessor,
 * WithStringAccessor, and WithNoAccessor) cover the ins and outs of when
 * you need ids and accessors.
 */
export type WithFunctionAccessor = {
    /**
     * This function is used to build the data model for your
     * column. The data returned by an accessor should be primitive
     * and sortable.  The column's value is looked up on the original
     * row using this accessor function, eg. If your column's accessor
     * is `row => row.firstName`, then its value would be determined by
     * passing the row to this function and using the resulting value.
     */
    accessor: TableColumnAccessor<any>;
    /**
     * Required if `accessor` is a function. This is the unique ID for
     * the column. It is used by reference in things like sorting, grouping,
     * filtering etc.
     */
    id: string;
};
/**
 * Columns normally either have a function or string accessor. Technically
 * the can also have no accessor. These types (WithFunctionAccessor,
 * WithStringAccessor, and WithNoAccessor) cover the ins and outs of when
 * you need ids and accessors.
 */
export type WithStringAccessor = {
    /**
     * This string is used to build the data model for your
     * column. The data returned by an accessor should be
     * primitive and sortable. The column's value is looked up
     * on the original row via this key, e.g. if your column's
     * accessor is firstName then its value would be read from
     * `row['firstName']`. You can also specify deeply nested values
     * with accessors like info.cpu or even `address[0].memory`. If
     * you need to escape the special meaning of dots you can wrap
     * the accessor string in quotes.
     */
    accessor: string;
    /**
     * If a string accessor is used, it defaults as the
     * column ID, but can be overridden if necessary by this ID.
     */
    id?: string;
};
/**
 * Columns normally either have a function or string accessor. Technically
 * the can also have no accessor. These types (WithFunctionAccessor,
 * WithStringAccessor, and WithNoAccessor) cover the ins and outs of when
 * you need ids and accessors.
 */
export type WithNoAccessor = {
    id: string;
    accessor?: never;
};
export type UseColumnConfigOptions = SparklineColumn | MeterbarColumn | {
    columnType?: ColumnType;
    config?: never;
};
/**
 * Intended to represent one column in a table. A `SingleColumn`
 * has semi-optional `accessor` and `id` properties in addition
 * to the other common properties.
 */
export type SingleColumn = ColumnOptions & UseColumnConfigOptions & UseColumnUserActionsProps & UseThresholdOptions & UseFormattingOptions & (WithStringAccessor | WithFunctionAccessor | WithNoAccessor);
/**
 * Intended to represent groups of columns in a table. A column
 * group has a `columns` property in addition to the other common
 * properties.
 */
export type ColumnGroup = ColumnOptions & WithNoAccessor & {
    /**
     * Columns can either be a single column or a column group.
     * If defined, the column will act as a header group. In
     * general, columns can be recursively nested as much as needed.
     */
    columns: TableColumn[];
};
/**
 * Properties common to single columns and column groups.
 */
export type ColumnOptions = {
    /**
     * Header of the column which can be a string
     * (e.g. 'First name' or 'Last name') or a more
     * complex react element (e.g. A Checkbox and text).
     */
    header?: string | ReactElement | ReactFragment | ReactPortal | ((props: unknown) => React.ReactNode);
    /**
     * Optional renderer for a cell.
     * This function (or component) is primarily used for
     * formatting the column value, eg. If your column accessor
     * returns a date object, you can use a function to
     * format that date to a readable format.
     */
    cell?: TableCellRenderer<{
        cell: any;
        value: any;
        row: TableRow<any>;
        column: TableColumn;
    }>;
    /**
     * Width of the column in pixels e.g. 200
     */
    width?: number;
    /**
     * Minimum width of the column in pixels. e.g. 100
     */
    minWidth?: number;
    /**
     * Maximum width of the column in pixels. e.g. 200
     */
    maxWidth?: number;
    /**
     * Only relevant for expandable column. Can be used to
     * determine whether it is allowed to expand this row.
     */
    canExpand?: (row: TableRow<any>) => boolean;
    /**
     * Wrap contents of cells in this column.
     * When set to `true` content of cell is wrapped,
     * when set to `false` content is truncated.
     */
    lineWrap?: boolean;
    /**
     * Sets the font style of the column.
     */
    fontStyle?: 'text' | 'code';
    /**
     * Optional aria label for columns with non-readable header content.
     */
    'aria-label'?: string;
    /**
     * Only relevant for sub rows.
     * Determines whether the sub rows of the passed row can be opened or not (disable the trigger).
     * @defaultValue false
     */
    disableSubRows?: (row: TableRow<any>) => boolean;
    /**
     * Only relevant for sub rows. Defines the accessor for the sub rows data.
     * Can either be a string (with dot notation) or an accessor function.
     * @defaultValue 'subRows'
     */
    subRowsAccessor?: ((row: any, index: number) => any[]) | string;
} & UseColumnTypesColumnOptions & UseResizeColumnsOptions & UseColumnSizesColumnOptions & UseAlignmentColumnOptions & UseSortByColumnOptions;
/**
 * Rule for sorting a column.
 */
export type TableSortingRule = {
    /** id of the column to use for sorting the table. */
    id: string;
    /**
     * `true` for descending, `false` for ascending.
     * Undefined for unsorted.
     * @defaultValue undefined
     */
    desc?: boolean;
};
/**
 * Compares two rows by a given column.
 *
 * @param rowA - Object containing all values of the first row.
 * @param rowB - Object containing all values of the second row.
 * @param columnId - The id of the column to be compared.
 * @param isDescending - Determines whether the sorting algorithm
 * intends to sort values in descending order - the value of this
 * parameter does not influence value comparison and is only
 * relevant when row indices are used to compensate for the unstable
 * sorting algorithm used by the react-table library in v7.
 *
 * @returns `0` if both rows are equal, a number greater than `0` if
 * `rowA` is larger or a number less than `0` if `rowB` is larger.
 */
export type CompareRows = (rowA: {
    values: {
        [columnId: string]: any;
    };
}, // eslint-disable-line @typescript-eslint/no-explicit-any
rowB: {
    values: {
        [columnId: string]: any;
    };
}, // eslint-disable-line @typescript-eslint/no-explicit-any
columnId: string, isDescending: boolean) => number;
/**
 * Options for sorting columns.
 */
export type UseSortByColumnOptions = {
    /**
     * Setting to true disables sorting for this column even
     * if sorting is enabled globally.
     */
    disableSortBy?: boolean;
    /**
     * Setting to true means the first sorting direction for
     * this column will be descending instead of ascending.
     */
    sortDescFirst?: boolean;
    /**
     * Setting this to true means the underlying sorting
     * direction will be inverted but the UI will not. This
     * could be useful for example where a lower score is better.
     */
    sortInverted?: boolean;
    /**
     * Used to compare 2 rows of data and order them correctly.
     * If a function is passed, it must be memoized.
     * @defaultValue 'alphanumeric'
     */
    sortType?: 'basic' | 'datetime' | 'alphanumeric' | CompareRows;
};
/**
 * Options for DataTable look
 */
export interface TableVariantConfig {
    /**
     * rowSeparation can be set to 'horizontalDividers' which will provide lines between rows or
     * can be set to 'zebraStripes' which will provide alternate row coloring.
     * @defaultValue 'none'
     */
    rowSeparation?: 'none' | 'horizontalDividers' | 'zebraStripes';
    /**
     * If true provides vertical lines between the columns.
     * @defaultValue false
     */
    verticalDividers?: boolean;
    /**
     * If true provides a border for the table.
     * @defaultValue false
     */
    contained?: boolean;
    /**
     * rowDensity adds spacing around the content inside the row
     * with minimal space for 'condensed', maximum spacing for 'comfortable' and
     * 'default' being medium spacing.
     * @defaultValue 'default'
     */
    rowDensity?: RowDensity;
    /**
     * fontStyle, sets the font style for the entire data table.
     * This does not overwrite, any fontStyle set at the lower level, like columns etc.
     * @defaultValue 'text'
     */
    fontStyle?: 'text' | 'code';
}
export type RowDensity = 'default' | 'condensed' | 'comfortable';
/**
 * Options for resizing columns.
 */
export interface UseResizeColumnsOptions {
    /**
     * When set to true, resizing is disabled for this column.
     * @defaultValue false
     */
    disableResizing?: boolean;
}
/**
 * Adapted options for configuring value thresholds for table columns.
 */
export type UseThresholdOptions = ThresholdOptions<Threshold>;
/**
 * Used in combination with SimpleTable.
 */
export type SimpleTableColumn = SingleColumn & Partial<UseAlignmentColumnOptions>;
/**
 * Type of cell renderer.
 */
export type TableCellRenderer<Props> = ((props: unknown) => React.ReactNode) | ComponentType<Props> | ReactElement | ReactText | ReactFragment;
/**
 * Type of header renderer.
 */
export type TableHeaderRenderer<Props> = ((props: unknown) => React.ReactNode) | ComponentType<Props> | ReactElement | ReactText | ReactFragment;
/**
 * Row properties
 */
export type TableRow<D extends Record<string, unknown> = Record<string, unknown>> = {
    /**
     * The index of the original row in the data array that
     * was passed to DataTable. If this row is a subRow, it is
     * the original index within the parent row's subRows array.
     */
    index: number;
    /**
     * The original row object from the data array that was used
     * to materialize this row.
     */
    original: D;
    /**
     * A map of this row's resolved values by columnId,
     * eg. `{ firstName: 'John', lastName: 'Smith' }`
     */
    values: Record<string, any>;
};
/**
 * Cell properties
 */
export type TableCell = {
    /**
     * The cell value.
     */
    value: any;
};
/**
 * Column accessor which can be used instead of a
 * simple string.
 */
export type TableColumnAccessor<D extends Record<string, unknown> = Record<string, unknown>> = (
/**
 * The original row object from the data array that was used
 * to materialize this row.
 */
originalRow: D, 
/**
 * The index of the original row in the data array that
 * was passed to DataTable. If this row is a subRow, it is
 * the original index within the parent row's subRows array.
 */
index: number, sub: {
    /**
     * If the row is a materialized group row, this property
     * is the array of materialized subRows that were grouped
     * inside of this row.
     */
    subRows: D[];
    /**
     * If the row is a materialized group row, this is the
     * grouping depth at which this row was created.
     */
    depth: number;
    /**
     *
     */
    data: D[];
}) => unknown;
/**
 * DataTable Ref
 */
export interface DataTableRef {
    readonly element: HTMLDivElement | null;
    /** Returns the current config of the DataTable.*/
    getConfig: () => DataTableContextConfig;
    /** Returns a copy of the sorted data displayed on the current page. */
    getCurrentPageData: () => TableRow[];
    /**
     * Downloads table data, without the hidden columns.
     * @param subset - 'all' to download the entire table data (without the hidden columns),
     * 'page' to download all data on the current table page, 'selected' to
     * download only the selected data (rows with checked checkboxes).
     */
    downloadData: (subset: 'all' | 'page' | 'selected') => void;
}
/**
 * Props for the DataTable's sub row cell.
 */
export type DataTableSubRowsCellProps = {
    /**
     * The cell's corresponding row.
     */
    row: any;
    /**
     * All table rows
     */
    rows: any[];
    /**
     * Updates the open sub rows. If a parent row is closed, all nested sub rows are closed and deselected as well.
     *
     * @param update - either the row id, or a boolean if all sub rows should be opened/closed
     */
    updateOpenSubRows: (update: string | boolean) => void;
    /**
     * The maximum sub row depth of the currently open sub rows.
     */
    subRowsDepth: number;
    /**
     * The actual index of the current row, considers things like sorting and sub rows.
     */
    currentRowIndex: number;
    /**
     * The table state containing the current page index and page size.
     */
    state: {
        pageIndex: number;
        pageSize?: number;
    };
};
/**
 * Props for the DataTable's sub row header.
 */
export type DataTableSubRowsHeaderProps = {
    /**
     * Updates the open sub rows. If a parent row is closed, all nested sub rows are closed and deselected as well.
     *
     * @param update - either the row id, or a boolean if all sub rows should be opened/closed
     */
    updateOpenSubRows: (update: string | boolean) => void;
    /**
     * Whether all sub rows are currently open or not.
     */
    allSubRowsOpen: boolean;
    /**
     * The maximum sub row depth of the currently open sub rows.
     */
    subRowsDepth: number;
};
